using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace SargasPC {
 public sealed partial class Window {
  private void AutomationTick(){if(core.SharedReadOnlyEngine)return;if(busy||IsDisposed||!Enabled||OwnedForms.Length>0||BackgroundBlocked())return;long now=DateTime.UtcNow.Ticks;if(core.Config.AutoDbUpdate&&!AutonomyPolicy.ClockValid(core.Config,now)){status.Text=AutonomyPolicy.Status(core.Config,now);return;}if(!AutonomyPolicy.UpdateDue(core.Config,now))return;if(!core.HasLocalEngine){status.Text="Automatiniam atnaujinimui pirmiausia paruoškite vietinį ClamAV.";return;}Run("Automatinis ClamAV bazių atnaujinimas",()=>{string result=core.ScheduledLocalEngineUpdate();if(core.Config.AutoDbSuccessAt>0&&!IsDisposed)BeginInvoke((Action)delegate{if(!IsDisposed)RestoreSavedMonitor();});return result;},true);}

  private void RestoreSavedMonitor(){if(folderMonitor!=null||!core.Config.RestoreWatch||!core.Config.SavedWatchEnabled)return;try{string p=core.Config.SavedWatchDirectory;if(!core.HasLocalEngine||!Directory.Exists(p)||!MonitorSafety.SafeWatchRoot(p,core.Root,AppDomain.CurrentDomain.BaseDirectory))throw new IOException("Išsaugotas aplankas ar vietinis variklis nepasiekiamas.");EngineSafety.ValidateDatabaseFiles(core.EngineDatabase);folderMonitor=new FolderMonitor(p);folderMonitor.SeedExisting();monitoredDirectory=Path.GetFullPath(p);monitorLocalEngine=true;monitorAutoQuarantine=core.Config.SavedAutoQuarantine;nextMonitorAt=0;watchTimer.Start();status.Text="Aplanko stebėjimas atkurtas: "+Data.Clean(p)+". Karantinui tebėra taikomos parengties ribos.";}catch(IOException e){StopMonitor();status.Text="STEBĖJIMAS NEATKURTAS: "+Data.Clean(e.Message);try{core.History("Stebėjimas po paleidimo neatkurtas: "+Data.Clean(e.Message));}catch(IOException){}}catch(UnauthorizedAccessException){StopMonitor();status.Text="STEBĖJIMAS NEATKURTAS: nėra prieigos teisių.";}}
  private void AutomationSettings(){using(var d=new Form{Text="Automatika ir stebėjimo atkūrimas",Width=790,Height=720,StartPosition=FormStartPosition.CenterParent}){
   var info=new Label{Left=18,Top=18,Width=730,Height=150,Text=AutonomyPolicy.Status(core.Config,DateTime.UtcNow.Ticks)+"\r\nVeikia tik paleistoje SARGON programoje, taip pat sumažinus langą. Windows paleistį įjunkite atskirame foninio režimo meniu. Sistemos paslaugos nėra. Atnaujinimai ir skenavimai vykdomi po vieną. Po nesėkmės laukiama 30 min.–6 val.; normaliai tikrinama kas 24 val."};
   var updates=new CheckBox{Left=18,Top=180,Width=730,Height=55,Text="Automatiškai atnaujinti vietinio ClamAV bazes (kas 24 val.)",Checked=core.Config.AutoDbUpdate};
   var controls=new CheckBox{Left=18,Top=245,Width=730,Height=70,Text="Po automatinio atnaujinimo atlikti neutralų ir EICAR bandymą",Checked=core.Config.AutoDetectionControl};
   var restore=new CheckBox{Left=18,Top=325,Width=730,Height=70,Text="Po paleidimo atkurti pasirinktą aplanką ir jo karantino pasirinkimą",Checked=core.Config.RestoreWatch};
   var note=new Label{Left=18,Top=405,Width=730,Height=160,Text="FreshClam jungiasi prie oficialių bazių serverių: perduodamas IP, jūsų failai nesiunčiami. Atsisiuntimas gali būti didelis. EICAR žymuo nevykdomas; kita antivirusinė gali įspėti arba jį pašalinti — tada kontrolė nepatvirtinama. Atnaujinus bazes ankstesnė aptikimo kontrolė panaikinama. Automatinis karantinas galimas tik praėjus naujai kontrolei. Visos sistemos apsaugos garantijos nėra."};
   var save=new Button{Left=18,Top=580,Width=730,Height=50,Text="Išsaugoti automatikos nuostatas"};
   d.Controls.AddRange(new Control[]{info,updates,controls,restore,note,save});save.Click+=(s,e)=>{bool u=core.Config.AutoDbUpdate,c=core.Config.AutoDetectionControl,r=core.Config.RestoreWatch;try{core.Config.AutoDbUpdate=updates.Checked;core.Config.AutoDetectionControl=controls.Checked;core.Config.RestoreWatch=restore.Checked;core.SaveSettings();d.Close();RestoreSavedMonitor();AutomationTick();}catch(Exception error) when(error is IOException||error is UnauthorizedAccessException){core.Config.AutoDbUpdate=u;core.Config.AutoDetectionControl=c;core.Config.RestoreWatch=r;MessageBox.Show(d,"Nuostatų nepavyko išsaugoti; pakeitimai netaikomi.");}};ThemeDialog(d);d.ShowDialog(this);
  }}
 }
}
